const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let data={systems:[],payments:[]};
const money=c=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format((c||0)/100);
const date=v=>v?new Intl.DateTimeFormat('pt-BR',{timeZone:'UTC'}).format(new Date(v+'T12:00:00Z')):'—';
const label={active:'Ativo',paused:'Pausado',cancelled:'Cancelado',open:'Em aberto',overdue:'Atrasado',paid:'Pago',waived:'Isento'};
async function api(path,options={}){const r=await fetch(path,{...options,headers:{'content-type':'application/json',...(options.headers||{})}});const j=await r.json().catch(()=>({}));if(r.status===401){showLogin();throw new Error(j.error||'Sessão expirada');}if(!r.ok)throw new Error(j.error||'Não foi possível concluir');return j}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function showLogin(){ $('#login').classList.remove('hidden');$('#app').classList.add('hidden') }
function showApp(){ $('#login').classList.add('hidden');$('#app').classList.remove('hidden') }
function isOverdue(p){return p.status==='open'&&p.due_date<new Date().toISOString().slice(0,10)}
function paymentStatus(p){return isOverdue(p)?'overdue':p.status}
async function load(){data=await api('/api/admin/overview');render();showApp()}
function render(){const active=data.systems.filter(s=>s.status==='active');const mrr=active.reduce((n,s)=>n+s.monthly_fee_cents,0);const profit=active.reduce((n,s)=>n+s.monthly_profit_cents,0);const open=data.payments.filter(p=>p.status==='open').reduce((n,p)=>n+p.amount_cents,0);$('#metrics').innerHTML=[['◫','Sistemas ativos',active.length,'na carteira'],['R$','Receita mensal',money(mrr),'MRR contratado'],['↗','Lucro mensal',money(profit),'após custos'],['!','A receber',money(open),`${data.payments.filter(p=>p.status==='open').length} mensalidade(s)`]].map(m=>`<article class="metric"><div class="metric-top"><span>${m[1]}</span><span class="metric-icon">${m[0]}</span></div><strong>${m[2]}</strong><small>${m[3]}</small></article>`).join('');
$('#systemCards').innerHTML=data.systems.slice(0,5).map(s=>`<div class="system-card"><div><h4>${esc(s.business_name)}</h4><small>${esc(s.segment)} · desde ${date(s.start_date)}</small></div><div class="money"><strong>${money(s.monthly_fee_cents)}</strong><small>Lucro ${money(s.monthly_profit_cents)}/mês</small></div><span class="status ${s.status}">${label[s.status]}</span></div>`).join('')||'<p class="empty">Nenhum sistema cadastrado.</p>';
const next=data.payments.filter(p=>p.status==='open').sort((a,b)=>a.due_date.localeCompare(b.due_date)).slice(0,6);$('#upcoming').innerHTML=next.map(p=>`<div class="upcoming-item"><div><strong>${esc(p.business_name)}</strong><small>${p.reference_month} · ${date(p.due_date)}</small></div><div class="money"><strong>${money(p.amount_cents)}</strong><small class="${isOverdue(p)?'overdue-text':''}">${isOverdue(p)?'Atrasado':'Em aberto'}</small></div></div>`).join('')||'<p class="empty">Tudo em dia.</p>';renderSystems();renderPayments();fillSystemSelect()}
function renderSystems(){const q=$('#systemSearch').value.toLowerCase(),f=$('#statusFilter').value;const rows=data.systems.filter(s=>(!f||s.status===f)&&(`${s.business_name} ${s.segment}`.toLowerCase().includes(q)));$('#systemsTable').innerHTML=`<table><thead><tr><th>CLIENTE</th><th>STATUS</th><th>INÍCIO</th><th>MENSALIDADE</th><th>CUSTO</th><th>LUCRO</th><th>PAYBACK</th><th></th></tr></thead><tbody>${rows.map(s=>`<tr><td><strong>${esc(s.business_name)}</strong><small>${esc(s.segment)}</small></td><td><span class="status ${s.status}">${label[s.status]}</span></td><td>${date(s.start_date)}</td><td>${money(s.monthly_fee_cents)}</td><td>${money(s.monthly_cost_cents)}</td><td><strong>${money(s.monthly_profit_cents)}</strong></td><td>${s.payback_months?s.payback_months+' meses':'Em levantamento'}</td><td><button class="action edit-system" data-id="${s.id}">Editar</button></td></tr>`).join('')}</tbody></table>`;$$('.edit-system').forEach(b=>b.onclick=()=>openSystem(Number(b.dataset.id)))}
function renderPayments(){const q=$('#paymentSearch').value.toLowerCase(),f=$('#paymentFilter').value;const rows=data.payments.filter(p=>(!f||paymentStatus(p)===f)&&(`${p.business_name} ${p.reference_month}`.toLowerCase().includes(q)));$('#paymentsTable').innerHTML=`<table><thead><tr><th>CLIENTE</th><th>REFERÊNCIA</th><th>VENCIMENTO</th><th>VALOR</th><th>STATUS</th><th>PAGAMENTO</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td><strong>${esc(p.business_name)}</strong></td><td>${p.reference_month}</td><td>${date(p.due_date)}</td><td><strong>${money(p.amount_cents)}</strong></td><td><span class="status ${paymentStatus(p)}">${label[paymentStatus(p)]}</span></td><td>${p.paid_at?date(p.paid_at):'—'}</td><td>${p.status==='open'?`<button class="action pay" data-pay="${p.id}">Marcar como pago</button>`:`<button class="action" data-reopen="${p.id}">Reabrir</button>`}</td></tr>`).join('')}</tbody></table>`;$$('[data-pay]').forEach(b=>b.onclick=()=>updatePayment(Number(b.dataset.pay),'paid'));$$('[data-reopen]').forEach(b=>b.onclick=()=>updatePayment(Number(b.dataset.reopen),'open'))}
function esc(v=''){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function go(view){$$('.view').forEach(v=>v.classList.add('hidden'));$(`#${view}View`).classList.remove('hidden');$$('.nav').forEach(n=>n.classList.toggle('active',n.dataset.view===view));$('#pageTitle').textContent={overview:'Visão geral',systems:'Sistemas',payments:'Mensalidades'}[view]}
function openSystem(id){const f=$('#systemForm');f.reset();const s=data.systems.find(x=>x.id===id);$('#systemModalTitle').textContent=s?'Editar sistema':'Novo sistema';if(s){for(const [k,v] of Object.entries(s)){const e=f.elements[k];if(e)e.value=k.endsWith('_cents')?(v/100):v??''}f.elements.monthly_fee.value=s.monthly_fee_cents/100;f.elements.monthly_cost.value=s.monthly_cost_cents/100;f.elements.project_cost.value=s.project_cost_cents==null?'':s.project_cost_cents/100}f.elements.id.value=id||'';$('#systemDialog').showModal()}
function fillSystemSelect(){$('#paymentForm').elements.system_id.innerHTML=data.systems.filter(s=>s.status!=='cancelled').map(s=>`<option value="${s.id}">${esc(s.business_name)}</option>`).join('')}
async function updatePayment(id,status){await api(`/api/admin/payments/${id}`,{method:'PUT',body:JSON.stringify({status})});toast(status==='paid'?'Pagamento confirmado':'Mensalidade reaberta');await load()}
$('#loginForm').onsubmit=async e=>{e.preventDefault();$('#loginError').textContent='';try{await api('/api/admin/login',{method:'POST',body:JSON.stringify({password:$('#password').value})});$('#password').value='';await load()}catch(err){$('#loginError').textContent=err.message}};
$('#logout').onclick=async()=>{await api('/api/admin/logout',{method:'POST'}).catch(()=>{});showLogin()};$$('.nav').forEach(n=>n.onclick=()=>go(n.dataset.view));$$('[data-go]').forEach(n=>n.onclick=()=>go(n.dataset.go));$('#newSystem').onclick=()=>openSystem();$('#systemSearch').oninput=renderSystems;$('#statusFilter').onchange=renderSystems;$('#paymentSearch').oninput=renderPayments;$('#paymentFilter').onchange=renderPayments;
$('#systemForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,body=Object.fromEntries(new FormData(f));const id=body.id;delete body.id;try{await api(id?`/api/admin/systems/${id}`:'/api/admin/systems',{method:id?'PUT':'POST',body:JSON.stringify(body)});$('#systemDialog').close();toast(id?'Sistema atualizado':'Sistema cadastrado');await load()}catch(err){f.querySelector('.form-error').textContent=err.message}};
$('#newPayment').onclick=()=>{const f=$('#paymentForm');f.reset();fillSystemSelect();const now=new Date(),month=now.toISOString().slice(0,7);f.elements.reference_month.value=month;f.elements.due_date.value=`${month}-30`;const s=data.systems.find(x=>x.id===Number(f.elements.system_id.value));f.elements.amount.value=s?(s.monthly_fee_cents/100).toFixed(2):'';$('#paymentDialog').showModal()};$('#paymentForm').elements.system_id.onchange=e=>{const s=data.systems.find(x=>x.id===Number(e.target.value));if(s)$('#paymentForm').elements.amount.value=(s.monthly_fee_cents/100).toFixed(2)};
$('#paymentForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;try{await api('/api/admin/payments',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(f)))});$('#paymentDialog').close();toast('Mensalidade lançada');await load()}catch(err){f.querySelector('.form-error').textContent=err.message}};
$('#today').textContent=new Intl.DateTimeFormat('pt-BR',{dateStyle:'full'}).format(new Date());api('/api/admin/session').then(load).catch(showLogin);
